function isEqual(firstObj, secondObj) {
  const firstKeys = Object.keys(firstObj);
  const secondKeys = Object.keys(secondObj);
  return firstKeys.length === secondKeys.length && firstKeys.every(function (key) {
    return secondKeys.includes(key) && firstObj[key] === secondObj[key];
  });
}

const first = {
  property: 'value',
  anotherProperty: 'another value'
};

const second = {
  property: 'value',
  anotherProperty: 'another value'
};

const third = {
  property: 'value',
  anotherProperty: 'one more value'
};

isEqual(first, second); // true
isEqual(second, third); // false
